def historical_0101():
    raw = zlib.decompress(base64.b85decode(_DATA))
    if hashlib.sha256(raw).hexdigest() != GENERATION["records_sha256"]:
        raise ValueError("historical fixture byte identity differs")
    return json.loads(raw)
